CREATE TABLE IF NOT EXISTS cynexus_appl_market.portfolio_trade_plan (plan_id bigint PRIMARY KEY, principal_key text NOT NULL, tenant_key text NOT NULL, symbol text NOT NULL, instrument_type text NOT NULL, strategy text, thesis text, planned_entry_price numeric(20,8) NOT NULL, stop_loss_price numeric(20,8) NOT NULL, target_price numeric(20,8), planned_position_pct numeric(20,12), risk_amount numeric(28,8), expected_holding_days int, confidence_score numeric(10,4), market_regime text, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_portfolio_trade_plan_owner ON cynexus_appl_market.portfolio_trade_plan(tenant_key,principal_key,symbol);
